(()=>{
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');const W=960,H=550;let dpr=1,scale=1,offX=0,offY=0,last=0,acc=0,gameTime=0;let lives=100,cash=650,popped=0,wave=0,active=false,paused=false,speed=1,selectedType='dart',selectedTower=null,towers=[],bloons=[],shots=[],particles=[],spawnQueue=[],spawnTimer=0,roundElapsed=0,toastTimer=0,started=false;
const ui={lives:document.getElementById('lives'),cash:document.getElementById('cash'),popped:document.getElementById('popped'),wave:document.getElementById('wave'),count:document.getElementById('towerCount'),waveBtn:document.getElementById('waveBtn'),waveText:document.getElementById('waveBtnText'),waveHint:document.getElementById('waveHint'),progress:document.getElementById('progressFill'),toast:document.getElementById('toast'),callout:document.getElementById('waveCallout'),upgrade:document.getElementById('upgradePanel'),over:document.getElementById('gameOver')};
const path=[[-35,292],[106,292],[106,112],[310,112],[310,415],[520,415],[520,165],[730,165],[730,336],[850,336],[850,225],[990,225]];let segments=[],pathLength=0;for(let i=0;i<path.length-1;i++){let a=path[i],b=path[i+1],len=Math.hypot(b[0]-a[0],b[1]-a[1]);segments.push({a,b,len,start:pathLength});pathLength+=len}const types={dart:{name:'Dart Monkey',emoji:'🐒',cost:200,range:130,rate:.72,damage:1,color:'#f48c52',shotSpeed:430},ninja:{name:'Ninja Monkey',emoji:'🐵',cost:350,range:160,rate:.37,damage:1,color:'#a575d5',shotSpeed:530,camo:true},boomer:{name:'Boomerang',emoji:'🐒',cost:400,range:145,rate:1.08,damage:1,color:'#f4a537',shotSpeed:300},cannon:{name:'Little Cannon',emoji:'💣',cost:500,range:145,rate:1.55,damage:2,color:'#5e8795',shotSpeed:280,splash:48}};
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);scale=Math.min(canvas.width/W,canvas.height/H);offX=(canvas.width-W*scale)/2;offY=(canvas.height-H*scale)/2}new ResizeObserver(resize).observe(canvas);resize();
function posAt(dist){let d=Math.max(0,dist);for(const s of segments){if(d<=s.start+s.len){let t=(d-s.start)/s.len;return{x:s.a[0]+(s.b[0]-s.a[0])*t,y:s.a[1]+(s.b[1]-s.a[1])*t}}}return{x:path.at(-1)[0],y:path.at(-1)[1]}}
function distPath(x,y){let best=1e9;for(const s of segments){let dx=s.b[0]-s.a[0],dy=s.b[1]-s.a[1],t=Math.max(0,Math.min(1,((x-s.a[0])*dx+(y-s.a[1])*dy)/(s.len*s.len)));best=Math.min(best,Math.hypot(x-s.a[0]-dx*t,y-s.a[1]-dy*t))}return best}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.6}
function updateUI(){ui.lives.textContent=lives;ui.cash.textContent=cash;ui.popped.textContent=popped;ui.wave.textContent=wave;ui.count.textContent=towers.length;ui.waveText.textContent=active?'Round in progress…':`Start round ${wave+1}`;ui.waveHint.textContent=active?'Pop every bloon before it reaches the exit!':wave===0?'Place a defender, then start the round!':'Ready when you are, Ranger!';ui.progress.style.width=active?`${Math.max(3,100*(1-spawnQueue.length/(6+wave*3)))}%`:'0%';}
function drawBackground(){ctx.fillStyle='#a8d477';ctx.fillRect(0,0,W,H);
// grassy soft patches
for(let i=0;i<16;i++){let x=(i*173+42)%W,y=(i*97+21)%H;ctx.fillStyle=i%2?'#9fce70':'#b4dd81';ctx.globalAlpha=.35;ctx.beginPath();ctx.ellipse(x,y,70+(i%3)*15,38+(i%4)*7,(i%4)*.4,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// distant decorative shrubs/trees
for(const [x,y,r] of [[48,55,22],[250,66,21],[420,60,28],[640,73,23],[900,60,32],[56,475,29],[264,490,24],[437,500,28],[640,485,24],[910,480,28],[190,204,15],[594,490,14],[806,95,16]]){ctx.fillStyle='#659b5a';ctx.beginPath();ctx.ellipse(x+4,y+7,r*1.1,r*.48,0,0,7);ctx.fill();ctx.fillStyle='#6da961';ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();ctx.fillStyle='#82bb68';ctx.beginPath();ctx.arc(x-r*.28,y-r*.25,r*.65,0,7);ctx.fill();ctx.fillStyle='#9dcf75';ctx.beginPath();ctx.arc(x-r*.38,y-r*.38,r*.28,0,7);ctx.fill()}
// small flowers
for(let i=0;i<55;i++){let x=(i*197+71)%W,y=(i*131+18)%H;if(distPath(x,y)<61)continue;ctx.fillStyle=i%3===0?'#fff5b4':i%3===1?'#fff':'#efb5c3';ctx.beginPath();ctx.arc(x,y,1.8,0,7);ctx.fill();ctx.fillStyle='#dfbc57';ctx.beginPath();ctx.arc(x,y,0.8,0,7);ctx.fill()}
// route shadow and cream edges
ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();path.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle='#719652';ctx.lineWidth=83;ctx.stroke();ctx.beginPath();path.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle='#e7d6a4';ctx.lineWidth=75;ctx.stroke();ctx.beginPath();path.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle='#f3e7c4';ctx.lineWidth=65;ctx.stroke();
// path tiny dashes / pebbles
for(let d=22;d<pathLength;d+=34){let p=posAt(d);ctx.fillStyle='#e3d3ae';ctx.beginPath();ctx.ellipse(p.x+17,p.y-17,2.1,1.4,.4,0,7);ctx.fill()}
// start and exit signs
let st=posAt(15),en=posAt(pathLength-12);ctx.fillStyle='#fff9e6';ctx.beginPath();ctx.arc(st.x,st.y,20,0,7);ctx.fill();ctx.font='16px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('🚪',st.x,st.y);ctx.beginPath();ctx.arc(en.x,en.y,24,0,7);ctx.fillStyle='#fff0c1';ctx.fill();ctx.fillText('🏁',en.x,en.y);
// ponds / props behind route
ctx.fillStyle='#70c6bb';ctx.beginPath();ctx.ellipse(885,112,39,22,-.3,0,7);ctx.fill();ctx.strokeStyle='#d9f0c4';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#f2de8a';ctx.beginPath();ctx.ellipse(877,104,10,5,-.4,0,7);ctx.fill();ctx.fillStyle='#76a55e';for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(894+i*6,117+i*2,4,10,-.3,0,7);ctx.fill()}
}
function drawTower(t){let x=t.x,y=t.y;ctx.save();ctx.translate(x,y);let range=types[t.type].range+(t.level-1)*25;if(selectedTower===t){ctx.beginPath();ctx.arc(0,0,range,0,7);ctx.fillStyle='#ffffff24';ctx.fill();ctx.setLineDash([5,5]);ctx.strokeStyle='#ffffffbb';ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([])}ctx.fillStyle='#527547';ctx.beginPath();ctx.ellipse(1,10,19,9,0,0,7);ctx.fill();ctx.fillStyle='#d6c77e';ctx.beginPath();ctx.ellipse(0,7,17,7,0,0,7);ctx.fill();
if(t.type==='cannon'){ctx.fillStyle='#71858a';ctx.beginPath();ctx.arc(0,-8,14,0,7);ctx.fill();ctx.fillStyle='#42595f';ctx.save();ctx.rotate(t.angle||0);ctx.fillRect(0,-12,21,8);ctx.restore();ctx.strokeStyle='#9cb2ac';ctx.lineWidth=2;ctx.beginPath();ctx.arc(-4,-13,7,Math.PI,0);ctx.stroke();ctx.fillStyle='#3e545c';ctx.beginPath();ctx.arc(0,-7,4,0,7);ctx.fill()}else{ctx.fillStyle=t.type==='ninja'?'#51436c':t.type==='boomer'?'#8a623a':'#cc874a';ctx.beginPath();ctx.ellipse(0,-5,13,16,0,0,7);ctx.fill();ctx.fillStyle=t.type==='ninja'?'#8f79b1':'#e9b883';ctx.beginPath();ctx.arc(0,-17,11,0,7);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(4,-18,4,5,0,0,7);ctx.fill();ctx.fillStyle='#26352e';ctx.beginPath();ctx.arc(5,-18,1.8,0,7);ctx.fill();ctx.strokeStyle='#704632';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-12,4,.2,2.7);ctx.stroke();ctx.fillStyle=t.type==='ninja'?'#d9bce9':'#f3d09e';ctx.beginPath();ctx.ellipse(-3,-8,5,3,-.4,0,7);ctx.fill();if(t.type==='dart'){ctx.strokeStyle='#dfecad';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(6,-6);ctx.lineTo(15,-13);ctx.stroke()}if(t.type==='boomer'){ctx.strokeStyle='#e99c38';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(8,-5);ctx.lineTo(16,-12);ctx.lineTo(12,-2);ctx.stroke()}}
if(t.level>1){ctx.fillStyle='#fff2a1';ctx.beginPath();ctx.arc(-12,-27,6,0,7);ctx.fill();ctx.fillStyle='#917327';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText(''+(t.level-1),-12,-24)}ctx.restore()}
const colors={red:'#f35e68',blue:'#52a4e7',green:'#66c75f',yellow:'#f5ca45',pink:'#ef86ad',black:'#53535e',white:'#f7f5eb',lead:'#667786',ceramic:'#ad6b45',moab:'#637488'};
function drawBloon(b){let p=posAt(b.dist),r=b.kind==='moab'?20:b.kind==='ceramic'?12:9;ctx.save();ctx.translate(p.x,p.y+Math.sin(gameTime*7+b.id)*1.5);if(b.kind==='moab'){ctx.fillStyle='#536a82';ctx.beginPath();ctx.ellipse(0,0,27,17,0,0,7);ctx.fill();ctx.fillStyle='#8498ad';ctx.beginPath();ctx.ellipse(-4,-5,17,7,-.15,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#e9cf89';ctx.beginPath();ctx.moveTo(-14,12);ctx.lineTo(-19,22);ctx.lineTo(-7,15);ctx.fill();ctx.beginPath();ctx.moveTo(14,12);ctx.lineTo(19,22);ctx.lineTo(7,15);ctx.fill();ctx.fillStyle='#e8f4fc';ctx.beginPath();ctx.arc(9,-2,2,0,7);ctx.fill();ctx.fillStyle='#faefbd';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText('MOAB',0,3)}else{let c=colors[b.kind]||colors.red;ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(0,0,r*.82,r,0,0,7);ctx.fill();ctx.fillStyle='#ffffff88';ctx.beginPath();ctx.ellipse(-r*.28,-r*.38,r*.24,r*.34,-.5,0,7);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-3,r-1);ctx.lineTo(3,r-1);ctx.lineTo(0,r+6);ctx.fill();if(b.camo){ctx.strokeStyle='#35433c';ctx.lineWidth=1.4;ctx.setLineDash([2,2]);ctx.beginPath();ctx.arc(0,0,r+2,0,7);ctx.stroke();ctx.setLineDash([])}if(b.kind==='lead'){ctx.strokeStyle='#d2e0e5';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,r-2,0,7);ctx.stroke()}if(b.kind==='ceramic'){ctx.strokeStyle='#efd4ad';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(-5,-3);ctx.lineTo(5,2);ctx.moveTo(-4,4);ctx.lineTo(4,-3);ctx.stroke()}}ctx.restore()}
