for(let i=shots.length-1;i>=0;i--){let s=shots[i];if(s.kind==='boomer'){s.age+=dt;let dx=s.tx-s.x,dy=s.ty-s.y,d=Math.hypot(dx,dy);if(d>4){s.x+=dx/d*s.spd*dt;s.y+=dy/d*s.spd*dt}else if(s.age<.5){s.tx=s.originX;s.ty=s.originY;s.spd=390}else{shots.splice(i,1);continue}if(s.age>.75){shots.splice(i,1);continue}}else{let dx=s.tx-s.x,dy=s.ty-s.y,d=Math.hypot(dx,dy);if(d<s.spd*dt||!s.target||!bloons.includes(s.target)){if(s.kind==='bomb'){for(const b of [...bloons]){let p=posAt(b.dist);if(Math.hypot(p.x-s.tx,p.y-s.ty)<s.splash)pop(b,s.damage)}for(let j=0;j<12;j++)particles.push({x:s.tx,y:s.ty,vx:(Math.random()-.5)*130,vy:(Math.random()-.5)*130,life:.38,color:'#ffc65f',r:2+Math.random()*4})}else if(s.target&&bloons.includes(s.target))pop(s.target,s.damage);shots.splice(i,1);continue}s.x+=dx/d*s.spd*dt;s.y+=dy/d*s.spd*dt}if(s.kind==='boomer'){for(const b of [...bloons]){let p=posAt(b.dist);if(Math.hypot(p.x-s.x,p.y-s.y)<15)pop(b,s.damage)}}}
if(!spawnQueue.length&&!bloons.length){active=false;cash+=40+wave*3;showToast(`Round ${wave} cleared! +${40+wave*3} bananas 🍌`);if(wave===20)setTimeout(winGame,950)}
}for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=80*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}updateUI()}
function draw(){ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.setTransform(scale,0,0,scale,offX,offY);drawBackground();for(const t of towers)drawTower(t);for(const b of bloons)drawBloon(b);for(const s of shots){ctx.fillStyle=s.kind==='bomb'?'#374c53':s.kind==='boomer'?'#f7ac39':s.kind==='star'?'#eee29c':'#f7f6ce';ctx.beginPath();if(s.kind==='bomb'){ctx.arc(s.x,s.y,6,0,7);ctx.fill();ctx.fillStyle='#e9a355';ctx.fillRect(s.x-2,s.y-9,4,4)}else if(s.kind==='star'){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(gameTime*9);for(let q=0;q<4;q++){ctx.rotate(Math.PI/2);ctx.fillRect(-1.5,-8,3,7)}ctx.restore()}else{ctx.ellipse(s.x,s.y,s.kind==='boomer'?6:4,2,Math.atan2(s.ty-s.y,s.tx-s.x),0,7);ctx.fill()}}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/.45);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill()}ctx.globalAlpha=1;ctx.setTransform(1,0,0,1,0,0)}
