canvas.addEventListener('pointerdown',e=>{let p=worldPoint(e);if(p.x<0||p.y<0||p.x>W||p.y>H)return;let hit=[...towers].reverse().find(t=>Math.hypot(t.x-p.x,t.y-p.y)<25);if(hit){selectedType=null;document.querySelectorAll('.tower-card').forEach(x=>x.classList.remove('selected'));selectTower(hit);return}if(selectedType){addTower(selectedType,p.x,p.y)}else selectTower(null)});
